def solve(n, k, a):
    if k == 2:
        return min(1, sum(1 for x in a if x % 2 == 0))
    elif k == 3:
        return min(1, sum(1 for x in a if x % 3 == 0))
    elif k == 4:
        count_2 = sum(1 for x in a if x % 2 == 0)
        count_4 = sum(1 for x in a if x % 4 == 0)
        return min(1, count_2 - count_4 + 1)
    elif k == 5:
        return min(1, sum(1 for x in a if x % 5 == 0))

