MOD = 10**9 + 7

def count_good_integers(num1: str, num2: str, min_sum: int, max_sum: int) -> int:
    def digit_sum(n: str) -> int:
        return sum(int(digit) for digit in n)

    def count_up_to(n: str, min_sum: int, max_sum: int) -> int:
        @cache
        def dfs(pos: int, is_tight: bool, current_sum: int) -> int:
            if pos == len(n):
                return min_sum <= current_sum <= max_sum

            limit = int(n[pos]) if is_tight else 9
            count = 0
            for digit in range(limit + 1):
                new_is_tight = is_tight and digit == limit
                new_sum = current_sum + digit
                if new_sum > max_sum:
                    break
                count = (count + dfs(pos + 1, new_is_tight, new_sum)) % MOD
            return count

        return dfs(0, True, 0)

    return (count_up_to(num2, min_sum, max_sum) - count_up_to(str(int(num1) - 1), min_sum, max_sum) + MOD) % MOD

