class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        answer = []
        adjacent_count = 0

        for index_i, color_i in queries:
            if nums[index_i] != 0:
                # Check the left neighbor
                if index_i > 0 and nums[index_i - 1] == nums[index_i]:
                    adjacent_count -= 1
                # Check the right neighbor
                if index_i < n - 1 and nums[index_i + 1] == nums[index_i]:
                    adjacent_count -= 1

            nums[index_i] = color_i

            # Check the left neighbor
            if index_i > 0 and nums[index_i - 1] == nums[index_i]:
                adjacent_count += 1
            # Check the right neighbor
            if index_i < n - 1 and nums[index_i + 1] == nums[index_i]:
                adjacent_count += 1

            answer.append(adjacent_count)

        return answer

class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        max_length = 1
        start = 0
        consecutive_pairs = 0

        for end in range(1, len(s)):
            if s[end] == s[end - 1]:
                consecutive_pairs += 1

            while consecutive_pairs > 1:
                if s[start + 1] == s[start]:
                    consecutive_pairs -= 1
                start += 1

            max_length = max(max_length, end - start + 1)

        return max_length

