class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        total_imbalance = 0
        n = len(nums)

        for start in range(n):
            current_set = set()
            imbalance_count = 0

            for end in range(start, n):
                if nums[end] not in current_set:
                    current_set.add(nums[end])

                    # Check the imbalance condition
                    if nums[end] + 1 in current_set:
                        imbalance_count -= 1
                    if nums[end] - 1 in current_set:
                        imbalance_count += 1

                    total_imbalance += imbalance_count

        return total_imbalance

